<style>.pod-form{display:grid;gap:14px}.pod-form label{display:grid;gap:6px}.pod-form input,.pod-form select{padding:12px;font-size:16px}canvas{width:100%;height:180px;border:2px solid #334155;background:#fff;touch-action:none}.validation-summary,.field-error{color:#991b1b}.validation-summary{background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:12px}.requirements ul,.evidence-checklist ul{margin-bottom:0}.evidence-checklist{background:#f8fafc;border:1px solid #cbd5e1;border-radius:10px;padding:12px}button[disabled]{cursor:wait;opacity:.7}</style>
<script>(()=>{const form=document.getElementById('pod-form'),submit=document.getElementById('submit-pod'),errors=document.getElementById('client-errors'),list=document.getElementById('checklist');let submitting=false,signed=false,drawing=false;const items=[];const add=(label,test)=>items.push({label,test});const render=()=>{list.innerHTML='';const missing=[];items.forEach(item=>{const ok=item.test(),li=document.createElement('li');li.textContent=(ok?'✓ ':'✗ ')+item.label;li.style.color=ok?'#166534':'#991b1b';list.appendChild(li);if(!ok)missing.push(item.label.toLowerCase())});return missing};const receiver=document.getElementById('received-by-name');if(receiver)add('Receptor',()=>receiver.value.trim()!=='');const receiverType=document.getElementById('receiver-type');if(receiverType)add('Tipo de receptor',()=>receiverType.value!=='');const photo=document.getElementById('photo');if(photo){add('Fotografía',()=>photo.files.length>0);photo.addEventListener('change',()=>{document.getElementById('photo-status').textContent=photo.files.length?'Fotografía lista: '+photo.files[0].name:'Selecciona una fotografía de evidencia.';render()})}const canvas=document.getElementById('signature');if(canvas){const ctx=canvas.getContext('2d'),data=document.getElementById('signature-data'),point=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return[(p.clientX-r.left)*canvas.width/r.width,(p.clientY-r.top)*canvas.height/r.height]};add('Firma',()=>signed);['mousedown','touchstart'].forEach(n=>canvas.addEventListener(n,e=>{drawing=true;ctx.beginPath();ctx.moveTo(...point(e));e.preventDefault()},{passive:false}));['mousemove','touchmove'].forEach(n=>canvas.addEventListener(n,e=>{if(!drawing)return;ctx.lineWidth=3;ctx.lineTo(...point(e));ctx.stroke();signed=true;data.value=canvas.toDataURL('image/png');render();e.preventDefault()},{passive:false}));['mouseup','mouseleave','touchend'].forEach(n=>canvas.addEventListener(n,()=>drawing=false));document.getElementById('clear-signature').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);signed=false;data.value='';render()}}const latitude=document.getElementById('latitude');if(latitude){const longitude=document.getElementById('longitude'),accuracy=document.getElementById('accuracy'),status=document.getElementById('location-status');add('Ubicación',()=>latitude.value!==''&&longitude.value!==''&&accuracy.value!=='');document.getElementById('capture-location').onclick=()=>{if(!window.isSecureContext){status.textContent='La ubicación GPS requiere un contexto seguro (HTTPS) o un origen local permitido por el navegador.';return}if(!navigator.geolocation){status.textContent='La ubicación GPS no está disponible en este navegador.';return}status.textContent='Capturando ubicación...';navigator.geolocation.getCurrentPosition(p=>{latitude.value=p.coords.latitude;longitude.value=p.coords.longitude;accuracy.value=p.coords.accuracy;status.textContent='Ubicación capturada (precisión aproximada: ±'+Math.round(p.coords.accuracy)+' m).';render()},e=>status.textContent=({1:'Permiso de ubicación denegado.',2:'No fue posible determinar la ubicación GPS.',3:'La captura de ubicación agotó el tiempo de espera. Intenta nuevamente.'})[e.code]||'No fue posible capturar la ubicación GPS.',{enableHighAccuracy:true,timeout:15000,maximumAge:0})};if(latitude.value&&longitude.value&&accuracy.value)status.textContent='Ubicación capturada (precisión aproximada: ±'+Math.round(Number(accuracy.value))+' m).'}form.addEventListener('input',render);form.addEventListener('submit',e=>{if(submitting){e.preventDefault();return}const missing=render();if(missing.length){e.preventDefault();errors.textContent='Completa la evidencia pendiente: '+missing.join(', ')+'.';return}submitting=true;submit.disabled=true;submit.textContent='Finalizando entrega...'});render()})();</script>
